// Distribution / publish responsibility, extracted from the legacy god method's inline ADO.NET.
//
// SECURITY-HARDENED (output-neutral publish path ONLY — does NOT affect computed mission outputs,
// so corpus equivalence is preserved):
//   * PARAMETERIZED commands via SqlParameter (the legacy already used AddWithValue, but the
//     command text is now a fixed parameterized template with NO string concatenation of values);
//   * NO hardcoded connection string — it is INJECTED via PublishOptions (null by default);
//   * NO TrustServerCertificate=true (removed from the connection string entirely);
//   * still guarded by PublishEnabled=false (the demo default) so it NEVER connects.
//
// This is the async distribution method required by the clean-architecture brief. When publishing
// is disabled it returns immediately with PUBLISH_SKIPPED-free behavior (the legacy added no
// message when disabled, and neither do we), keeping the corpus output byte-identical.

using ForgeEvolve.ModernMds.Models;
using Microsoft.Data.SqlClient;

namespace ForgeEvolve.ModernMds.Distribution;

/// <summary>Publishes a computed mission (output-neutral). Single responsibility.</summary>
public interface IMissionPublisher
{
    /// <summary>
    /// Asynchronously publish the mission. Returns an optional status message to append to the
    /// result's message list (null = append nothing — matching the legacy's disabled-path behavior).
    /// Never throws: failures are swallowed and reported as a "PUBLISH_SKIPPED" message, exactly
    /// like the legacy.
    /// </summary>
    Task<string?> PublishAsync(
        MissionRequest request,
        DistanceResult distance,
        bool routeValid,
        bool taskingGoNoGo,
        MissionOptions options,
        CancellationToken cancellationToken = default);
}

/// <inheritdoc />
public sealed class MissionPublisher : IMissionPublisher
{
    public async Task<string?> PublishAsync(
        MissionRequest request,
        DistanceResult distance,
        bool routeValid,
        bool taskingGoNoGo,
        MissionOptions options,
        CancellationToken cancellationToken = default)
    {
        // Output-neutral guard: disabled by default. Append nothing (legacy parity).
        if (!options.Publish.PublishEnabled)
        {
            return null;
        }
        if (string.IsNullOrWhiteSpace(options.Publish.ConnectionString))
        {
            // No injected connection string => skip safely (never connects, no secret embedded).
            return "PUBLISH_SKIPPED";
        }

        try
        {
            await using var conn = new SqlConnection(options.Publish.ConnectionString);
            await conn.OpenAsync(cancellationToken).ConfigureAwait(false);
            await InsertMissionAsync(conn, request, distance.TotalDistanceNm, routeValid, taskingGoNoGo, cancellationToken)
                .ConfigureAwait(false);
            await InsertWaypointsAsync(conn, request, distance, cancellationToken).ConfigureAwait(false);
            return "PUBLISHED";
        }
        catch (Exception)
        {
            // Legacy parity: swallow and emit a skipped message; stays deterministic.
            return "PUBLISH_SKIPPED";
        }
    }

    private static async Task InsertMissionAsync(
        SqlConnection conn,
        MissionRequest request,
        double totalDistanceNm,
        bool routeValid,
        bool taskingGoNoGo,
        CancellationToken ct)
    {
        // Fixed parameterized literal (no value concatenation); values flow via SqlParameter only.
        await using SqlCommand cmd = conn.CreateCommand();
        cmd.CommandText =
            "INSERT INTO dbo.Missions (MissionId, Platform, Variant, TotalDistanceNm, RouteValid, TaskingGoNoGo) " +
            "VALUES (@id, @plat, @var, @dist, @valid, @go)";
        cmd.Parameters.Add(new SqlParameter("@id", request.MissionId));
        cmd.Parameters.Add(new SqlParameter("@plat", request.Platform));
        cmd.Parameters.Add(new SqlParameter("@var", request.Variant));
        cmd.Parameters.Add(new SqlParameter("@dist", totalDistanceNm));
        cmd.Parameters.Add(new SqlParameter("@valid", routeValid));
        cmd.Parameters.Add(new SqlParameter("@go", taskingGoNoGo));
        await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
    }

    private static async Task InsertWaypointsAsync(
        SqlConnection conn,
        MissionRequest request,
        DistanceResult distance,
        CancellationToken ct)
    {
        for (int i = 0; i < distance.LegDistancesNm.Count; i++)
        {
            await using SqlCommand cmd = conn.CreateCommand();
            cmd.CommandText =
                "INSERT INTO dbo.Waypoints (MissionId, Seq, LatDeg, LonDeg, LegDistanceNm) " +
                "VALUES (@id, @seq, @lat, @lon, @leg)";
            cmd.Parameters.Add(new SqlParameter("@id", request.MissionId));
            cmd.Parameters.Add(new SqlParameter("@seq", i));
            cmd.Parameters.Add(new SqlParameter("@lat", request.Waypoints[i].LatDeg));
            cmd.Parameters.Add(new SqlParameter("@lon", request.Waypoints[i].LonDeg));
            cmd.Parameters.Add(new SqlParameter("@leg", distance.LegDistancesNm[i]));
            await cmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
        }
    }
}

// Distance responsibility, extracted from the legacy god method.
//
// BEHAVIOR-PRESERVING — reproduces D1 and D2 EXACTLY:
//   D1: the legacy equirectangular kernel uses the RAW (unwrapped) longitude delta
//       (GeoMath.LegLegacyDistanceNm), so anti-meridian legs are wildly wrong.
//   D2: each leg is Math.Round(d, LegacyLegDecimals, MidpointRounding.ToEven) BEFORE being added
//       to the running total (naive left-to-right accumulation), so error accumulates.
// These are PRESERVED, not fixed — they are surfaced as ECP-recommended findings (see README).

using ForgeEvolve.ModernMds.Geometry;
using ForgeEvolve.ModernMds.Models;

namespace ForgeEvolve.ModernMds.Geometry;

/// <summary>Computes per-leg and total distance. Single responsibility.</summary>
public interface IDistanceCalculator
{
    DistanceResult Compute(IReadOnlyList<Waypoint> waypoints, MissionOptions options);
}

/// <inheritdoc />
public sealed class DistanceCalculator : IDistanceCalculator
{
    public DistanceResult Compute(IReadOnlyList<Waypoint> waypoints, MissionOptions options)
    {
        var legDistances = new List<double>();
        double total = 0.0;
        for (int i = 0; i < waypoints.Count - 1; i++)
        {
            var leg = new Leg(
                waypoints[i].LatDeg, waypoints[i].LonDeg,
                waypoints[i + 1].LatDeg, waypoints[i + 1].LonDeg);

            // D1: raw unwrapped dlon kernel.
            double d = GeoMath.LegLegacyDistanceNm(options.EarthRadiusNm, leg);

            // D2: banker's round each leg BEFORE summing (matches Python round / C# Math.Round).
            d = Math.Round(d, options.LegacyLegDecimals, MidpointRounding.ToEven);

            legDistances.Add(d);
            total += d; // naive left-to-right accumulation (part of D2 drift)
        }
        return new DistanceResult(legDistances, total);
    }
}

// Pure geometry kernels. Single responsibility: trigonometry only, no I/O, no state.
//
// BEHAVIOR-PRESERVING: these are byte-faithful to the legacy MissionProcessor helpers and the
// Python reference. Two distance kernels exist on purpose:
//   * LegLagacyDistanceNm — the D1 legacy kernel (RAW unwrapped dlon). PRESERVED.
//   * LegCorrectDistanceNm — the wrapped-dlon kernel (the ECP-recommended fix). NOT used by the
//     behavior-preserving path; provided so the ECP finding is concrete and testable.
// The bearing/turn helpers feed the bug-free shared route-validation path and use a wrapped dlon
// in BOTH legacy and modern, exactly as the reference specifies.

namespace ForgeEvolve.ModernMds.Geometry;

/// <summary>Stateless great-circle / equirectangular geometry kernels.</summary>
public static class GeoMath
{
    private const double DegToRad = Math.PI / 180.0;

    /// <summary>Normalize a longitude delta to [-180, 180] (correct anti-meridian handling).</summary>
    public static double WrapDlon(double dlon)
    {
        while (dlon > 180.0) dlon -= 360.0;
        while (dlon < -180.0) dlon += 360.0;
        return dlon;
    }

    /// <summary>
    /// D1 LEGACY leg distance (nm): equirectangular kernel using the RAW (unwrapped) longitude
    /// delta. Anti-meridian legs are wildly wrong by design — PRESERVED for equivalence.
    /// </summary>
    public static double LegLegacyDistanceNm(double earthRadiusNm, in Leg leg)
    {
        double dlonRad = (leg.Lon2 - leg.Lon1) * DegToRad; // D1: NO wrap
        return EquirectangularNm(earthRadiusNm, leg, dlonRad);
    }

    /// <summary>
    /// CORRECT leg distance (nm) with a wrapped longitude delta. This is the ECP-recommended fix
    /// for D1; it is NOT used by the behavior-preserving path (kept here for the finding's tests).
    /// </summary>
    public static double LegCorrectDistanceNm(double earthRadiusNm, in Leg leg)
    {
        double dlonRad = WrapDlon(leg.Lon2 - leg.Lon1) * DegToRad;
        return EquirectangularNm(earthRadiusNm, leg, dlonRad);
    }

    /// <summary>Initial great-circle bearing (deg, 0..360). Uses a WRAPPED dlon (bug-free shared).</summary>
    public static double InitialBearingDeg(in Leg leg)
    {
        double rlat1 = leg.Lat1 * DegToRad;
        double rlat2 = leg.Lat2 * DegToRad;
        double dlon = WrapDlon(leg.Lon2 - leg.Lon1) * DegToRad;
        double y = Math.Sin(dlon) * Math.Cos(rlat2);
        double x = Math.Cos(rlat1) * Math.Sin(rlat2)
                   - Math.Sin(rlat1) * Math.Cos(rlat2) * Math.Cos(dlon);
        double brg = Math.Atan2(y, x) / DegToRad;
        return (brg + 360.0) % 360.0;
    }

    /// <summary>Absolute turn between two bearings, in [0, 180].</summary>
    public static double TurnAngleDeg(double bearing1, double bearing2)
    {
        double d = Math.Abs(bearing2 - bearing1) % 360.0;
        return d > 180.0 ? 360.0 - d : d;
    }

    /// <summary>Shared equirectangular core: d = R * sqrt(x^2 + dlat^2), x = dlon*cos(meanLat).</summary>
    private static double EquirectangularNm(double earthRadiusNm, in Leg leg, double dlonRad)
    {
        double dlatRad = (leg.Lat2 - leg.Lat1) * DegToRad;
        double meanLatRad = ((leg.Lat1 + leg.Lat2) / 2.0) * DegToRad;
        double x = dlonRad * Math.Cos(meanLatRad);
        return earthRadiusNm * Math.Sqrt(x * x + dlatRad * dlatRad);
    }
}

/// <summary>An immutable ordered leg between two waypoints. Value type for cheap passing.</summary>
public readonly record struct Leg(double Lat1, double Lon1, double Lat2, double Lon2);

// Immutable domain records for the modernized mission processor.
//
// These replace the legacy pattern of parallel List<double> lats/lons and loose locals
// threaded through one ~200-line god method. They are init-only records (value semantics),
// nullable-enabled, and carry no behavior — behavior lives in the single-responsibility
// services. Field shapes mirror the legacy MissionRequest / MissionResult JSON exactly so the
// emitted output is byte-comparable to the legacy `legacyOutput` answer key.

namespace ForgeEvolve.ModernMds.Models;

/// <summary>A single waypoint (decimal degrees). Immutable.</summary>
public sealed record Waypoint(double LatDeg, double LonDeg);

/// <summary>
/// A parsed mission request. Replaces the legacy parallel-array + loose-local parse state.
/// </summary>
public sealed record MissionRequest
{
    public required string MissionId { get; init; }
    public required string Platform { get; init; }
    public required string Variant { get; init; }
    public required long LaunchEpochSec { get; init; }
    public required long DesiredTotEpochSec { get; init; }
    public required IReadOnlyList<Waypoint> Waypoints { get; init; }
}

/// <summary>
/// The computed mission result. Field order/shape matches the legacy MissionResult JSON so the
/// serialized output is directly comparable to the corpus `legacyOutput`.
/// </summary>
public sealed record MissionResult
{
    public required string MissionId { get; init; }
    public required IReadOnlyList<double> LegDistancesNm { get; init; }
    public required double TotalDistanceNm { get; init; }
    public required bool RouteValid { get; init; }
    public required long EstimatedTotEpochSec { get; init; }
    public required bool TotFeasible { get; init; }
    public required bool TaskingGoNoGo { get; init; }
    public required IReadOnlyList<string> Messages { get; init; }
}

/// <summary>Output of route validation: the GO/NO-GO flag plus any per-leg diagnostic messages.</summary>
public sealed record RouteValidation(bool RouteValid, IReadOnlyList<string> Messages);

/// <summary>Output of distance computation: per-leg distances (D1+D2 preserved) and their sum.</summary>
public sealed record DistanceResult(IReadOnlyList<double> LegDistancesNm, double TotalDistanceNm);

/// <summary>Output of the time-on-target estimator (D3 preserved): the estimate and feasibility.</summary>
public sealed record TotResult(long EstimatedTotEpochSec, bool TotFeasible);

// Injected, immutable options — the modern replacement for the legacy static mutable
// `LegacyConfig` global-state smell (DEBT.md item 2). Tunables and the (output-neutral) publish
// configuration are passed in via constructor injection instead of being read from global statics
// deep inside processing code.
//
// SECURITY (output-neutral publish path only): the hardcoded connection string with
// TrustServerCertificate=true is GONE. The connection string is injected (default null), and the
// publish path stays disabled by default (PublishEnabled=false) so the demo never connects.

namespace ForgeEvolve.ModernMds.Models;

/// <summary>
/// Physical/business tunables for the mission processor. Values match the legacy
/// <c>LegacyConfig</c> exactly so behavior is preserved; they are now injected and immutable.
/// </summary>
public sealed record MissionOptions
{
    public double EarthRadiusNm { get; init; } = 3440.065;
    public double MaxLegNm { get; init; } = 1500.0;
    public double MaxTurnDeg { get; init; } = 120.0;
    public double NominalSpeedNmPerSec { get; init; } = 0.15;
    public int TotTolSec { get; init; } = 120;
    public double MaxLegDLatDeg { get; init; } = 22.0;
    public double MaxLegDLonDeg { get; init; } = 22.0;

    /// <summary>D2 rounding precision (decimal places). Preserved from the legacy quirk.</summary>
    public int LegacyLegDecimals { get; init; } = 8;

    /// <summary>
    /// Synthetic leap-second boundaries (fictional placeholders). The legacy estimator OMITS this
    /// adjustment (D3); the table is retained so the ECP-recommended fix has the data available.
    /// </summary>
    public IReadOnlyList<long> SyntheticLeapBoundaries { get; init; } = new long[]
    {
        1_000_000_000L, 1_100_000_000L, 1_200_000_000L, 2_000_000_000L, 4_000_000_000L,
    };

    /// <summary>The injected publish configuration (output-neutral; disabled by default).</summary>
    public PublishOptions Publish { get; init; } = new();
}

/// <summary>
/// Output-neutral publish configuration. Hardened vs. the legacy: NO hardcoded connection string
/// and NO TrustServerCertificate=true. The connection string is injected (null by default) and the
/// path is disabled by default, so the demo never opens a connection.
/// </summary>
public sealed record PublishOptions
{
    /// <summary>When false (the demo default) the publish path never connects.</summary>
    public bool PublishEnabled { get; init; } = false;

    /// <summary>
    /// Injected connection string (no embedded credentials/secrets here, and no
    /// TrustServerCertificate=true). Null by default — required only when PublishEnabled=true.
    /// </summary>
    public string? ConnectionString { get; init; } = null;
}

// Parse responsibility, extracted from the legacy god method's inlined parse block.
//
// BEHAVIOR-PRESERVING: mirrors the legacy "defensive, swallow-and-emit-a-message" parse exactly:
//   * missing fields default (missionId/platform/variant => "", epochs => 0, waypoints => empty);
//   * any parse exception => a PARSE_ERROR outcome carrying the missionId parsed so far (the legacy
//     starts missionId="" and only assigns it before the throw point if it appeared first).
// The legacy parses missionId first inside the try, so on a malformed-but-present-missionId input
// the partially-parsed id may survive; to be byte-faithful we capture id incrementally and return
// whatever was parsed before the failure, exactly like the legacy local-variable behavior.

using System.Text.Json;
using ForgeEvolve.ModernMds.Models;

namespace ForgeEvolve.ModernMds.Parsing;

/// <summary>Discriminated outcome of a parse: either a request or a parse error.</summary>
public abstract record ParseOutcome
{
    public sealed record Ok(MissionRequest Request) : ParseOutcome;

    /// <summary>Parse failed. <paramref name="MissionId"/> is whatever was parsed before the fault.</summary>
    /// <summary>
    /// Parse failed. <paramref name="MissionId"/> and <paramref name="LaunchEpochSec"/> are whatever
    /// was parsed before the fault (legacy carries the partial launch epoch into estimatedTot).
    /// </summary>
    public sealed record Error(string MissionId, long LaunchEpochSec) : ParseOutcome;
}

/// <summary>Parses a MissionRequest JSON string. Single responsibility: deserialize + default.</summary>
public interface IMissionParser
{
    ParseOutcome Parse(string inputJson);
}

/// <inheritdoc />
public sealed class MissionParser : IMissionParser
{
    public ParseOutcome Parse(string inputJson)
    {
        // Track id and launch epoch incrementally so the parse-error path can carry the partial
        // values, exactly like the legacy local variables (estimatedTot = launchEpochSec on error).
        string missionId = string.Empty;
        long launch = 0L;
        try
        {
            using JsonDocument doc = JsonDocument.Parse(inputJson);
            JsonElement root = doc.RootElement;

            missionId = ReadString(root, "missionId");
            string platform = ReadString(root, "platform");
            string variant = ReadString(root, "variant");
            launch = ReadInt64(root, "launchEpochSec");
            long desiredTot = ReadInt64(root, "desiredTotEpochSec");
            IReadOnlyList<Waypoint> waypoints = ReadWaypoints(root);

            return new ParseOutcome.Ok(new MissionRequest
            {
                MissionId = missionId,
                Platform = platform,
                Variant = variant,
                LaunchEpochSec = launch,
                DesiredTotEpochSec = desiredTot,
                Waypoints = waypoints,
            });
        }
        catch (Exception)
        {
            // Legacy "swallow and emit a message" pattern. Preserve the values parsed so far.
            return new ParseOutcome.Error(missionId, launch);
        }
    }

    private static string ReadString(JsonElement root, string name) =>
        root.TryGetProperty(name, out JsonElement el) ? el.GetString() ?? string.Empty : string.Empty;

    private static long ReadInt64(JsonElement root, string name) =>
        root.TryGetProperty(name, out JsonElement el) ? el.GetInt64() : 0L;

    private static IReadOnlyList<Waypoint> ReadWaypoints(JsonElement root)
    {
        var waypoints = new List<Waypoint>();
        if (root.TryGetProperty("waypoints", out JsonElement wpEl)
            && wpEl.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement wp in wpEl.EnumerateArray())
            {
                double lat = wp.TryGetProperty("latDeg", out JsonElement laEl) ? laEl.GetDouble() : 0.0;
                double lon = wp.TryGetProperty("lonDeg", out JsonElement loEl) ? loEl.GetDouble() : 0.0;
                waypoints.Add(new Waypoint(lat, lon));
            }
        }
        return waypoints;
    }
}

// Route-validation responsibility, extracted from the legacy god method.
//
// BEHAVIOR-PRESERVING and BUG-FREE-SHARED: this is the degree-box + turn-rate validation that the
// reference and legacy share verbatim, so routeValid is preserved EXACTLY. Message ordering matches
// the legacy: ALL "LEG_OUT_OF_BOX:i" messages (the per-leg loop) are appended first, then ALL
// "TURN_EXCEEDED:(i+1)" messages (the bearings loop). The shared, wrapped-dlon geometry is used in
// both legacy and modern here — D1 does NOT apply to validation.

using System.Globalization;
using ForgeEvolve.ModernMds.Geometry;
using ForgeEvolve.ModernMds.Models;

namespace ForgeEvolve.ModernMds.Routing;

/// <summary>Validates a route's legs (degree box) and turns (turn-rate). Single responsibility.</summary>
public interface IRouteValidator
{
    RouteValidation Validate(IReadOnlyList<Waypoint> waypoints, MissionOptions options);
}

/// <inheritdoc />
public sealed class RouteValidator : IRouteValidator
{
    public RouteValidation Validate(IReadOnlyList<Waypoint> waypoints, MissionOptions options)
    {
        bool valid = true;
        var messages = new List<string>();
        var bearings = new List<double>();

        valid &= CheckLegBoxes(waypoints, options, messages, bearings);
        valid &= CheckTurns(bearings, options, messages);

        return new RouteValidation(valid, messages);
    }

    /// <summary>Per-leg degree-box check; also accumulates bearings for the turn check.</summary>
    private static bool CheckLegBoxes(
        IReadOnlyList<Waypoint> waypoints,
        MissionOptions options,
        List<string> messages,
        List<double> bearings)
    {
        bool valid = true;
        for (int i = 0; i < waypoints.Count - 1; i++)
        {
            var leg = ToLeg(waypoints, i);
            double dLat = Math.Abs(leg.Lat2 - leg.Lat1);
            double dLonWrapped = Math.Abs(GeoMath.WrapDlon(leg.Lon2 - leg.Lon1));
            if (dLat > options.MaxLegDLatDeg || dLonWrapped > options.MaxLegDLonDeg)
            {
                valid = false;
                messages.Add("LEG_OUT_OF_BOX:" + i.ToString(CultureInfo.InvariantCulture));
            }
            bearings.Add(GeoMath.InitialBearingDeg(leg));
        }
        return valid;
    }

    /// <summary>Consecutive-bearing turn-rate check.</summary>
    private static bool CheckTurns(
        IReadOnlyList<double> bearings,
        MissionOptions options,
        List<string> messages)
    {
        bool valid = true;
        for (int i = 0; i < bearings.Count - 1; i++)
        {
            double turn = GeoMath.TurnAngleDeg(bearings[i], bearings[i + 1]);
            if (turn > options.MaxTurnDeg)
            {
                valid = false;
                messages.Add("TURN_EXCEEDED:" + (i + 1).ToString(CultureInfo.InvariantCulture));
            }
        }
        return valid;
    }

    private static Leg ToLeg(IReadOnlyList<Waypoint> waypoints, int i) =>
        new(waypoints[i].LatDeg, waypoints[i].LonDeg, waypoints[i + 1].LatDeg, waypoints[i + 1].LonDeg);
}

// Serialization responsibility, extracted from the legacy god method's BuildResultJson.
//
// BEHAVIOR-PRESERVING: writes the same fields in the same order with the same Utf8JsonWriter
// formatting the legacy used, so the emitted JSON is directly comparable to the corpus
// `legacyOutput` (ModernCheck parses both sides and compares field-by-field).

using System.Text;
using System.Text.Json;
using ForgeEvolve.ModernMds.Models;

namespace ForgeEvolve.ModernMds.Serialization;

/// <summary>Serializes a <see cref="MissionResult"/> to the legacy-compatible JSON shape.</summary>
public interface IMissionResultSerializer
{
    string Serialize(MissionResult result);
}

/// <inheritdoc />
public sealed class MissionResultSerializer : IMissionResultSerializer
{
    public string Serialize(MissionResult result)
    {
        using var buffer = new MemoryStream();
        var opts = new JsonWriterOptions { Indented = false };
        using (var w = new Utf8JsonWriter(buffer, opts))
        {
            w.WriteStartObject();
            w.WriteString("missionId", result.MissionId);
            w.WriteStartArray("legDistancesNm");
            foreach (double d in result.LegDistancesNm) w.WriteNumberValue(d);
            w.WriteEndArray();
            w.WriteNumber("totalDistanceNm", result.TotalDistanceNm);
            w.WriteBoolean("routeValid", result.RouteValid);
            w.WriteNumber("estimatedTotEpochSec", result.EstimatedTotEpochSec);
            w.WriteBoolean("totFeasible", result.TotFeasible);
            w.WriteBoolean("taskingGoNoGo", result.TaskingGoNoGo);
            w.WriteStartArray("messages");
            foreach (string m in result.Messages) w.WriteStringValue(m);
            w.WriteEndArray();
            w.WriteEndObject();
        }
        return Encoding.UTF8.GetString(buffer.ToArray());
    }
}

// MissionService — the modern orchestration root that REPLACES the legacy god method.
//
// The legacy MissionProcessor.ProcessMission was one ~200-line method (cyclomatic complexity 49)
// that inlined parse + pre-validate diagnostics + route-validation + distance + TOT + tasking +
// publish + serialize. Here, each of those is a single-responsibility, injected collaborator
// (IMissionParser, IRouteValidator, IDistanceCalculator, ITotEstimator, ITaskingEvaluator,
// IMissionPublisher, IMissionResultSerializer). MissionService only SEQUENCES them and assembles
// the message list in the exact legacy order.
//
// BEHAVIOR-PRESERVING: the emitted JSON EQUALS the legacy `legacyOutput` for all 2000 corpus
// vectors. The D1/D2/D3 quirks live inside the distance/TOT collaborators and are reproduced
// exactly; they are NOT fixed here (ECP-recommended findings — see README.md).
//
// Message ordering (must match legacy / reference legacy_model):
//   ["LEGACY"] + <validation messages: LEG_OUT_OF_BOX:* then TURN_EXCEEDED:*>
//             + (routeValid ? [] : ["ROUTE_INVALID"])
//             + (taskingGoNoGo ? [] : ["TASKING_NO_GO"])
//             + <optional publish status, only when PublishEnabled=true>

using ForgeEvolve.ModernMds.Distribution;
using ForgeEvolve.ModernMds.Geometry;
using ForgeEvolve.ModernMds.Models;
using ForgeEvolve.ModernMds.Parsing;
using ForgeEvolve.ModernMds.Routing;
using ForgeEvolve.ModernMds.Serialization;
using ForgeEvolve.ModernMds.Tasking;
using ForgeEvolve.ModernMds.Timing;

namespace ForgeEvolve.ModernMds.Services;

/// <summary>
/// The modernized mission component's single entry point. Behaviorally equivalent to the legacy
/// <c>MissionProcessor.ProcessMission</c>.
/// </summary>
public sealed class MissionService
{
    private readonly IMissionParser _parser;
    private readonly IRouteValidator _routeValidator;
    private readonly IDistanceCalculator _distanceCalculator;
    private readonly ITotEstimator _totEstimator;
    private readonly ITaskingEvaluator _taskingEvaluator;
    private readonly IMissionPublisher _publisher;
    private readonly IMissionResultSerializer _serializer;
    private readonly MissionOptions _options;

    public MissionService(
        IMissionParser parser,
        IRouteValidator routeValidator,
        IDistanceCalculator distanceCalculator,
        ITotEstimator totEstimator,
        ITaskingEvaluator taskingEvaluator,
        IMissionPublisher publisher,
        IMissionResultSerializer serializer,
        MissionOptions options)
    {
        _parser = parser;
        _routeValidator = routeValidator;
        _distanceCalculator = distanceCalculator;
        _totEstimator = totEstimator;
        _taskingEvaluator = taskingEvaluator;
        _publisher = publisher;
        _serializer = serializer;
        _options = options;
    }

    /// <summary>
    /// Default-wired instance: behavior-preserving, publish disabled. Equivalent to constructing
    /// the legacy static processor. Provided for callers that don't run a DI container.
    /// </summary>
    public static MissionService CreateDefault(MissionOptions? options = null) =>
        new(
            new MissionParser(),
            new RouteValidator(),
            new DistanceCalculator(),
            new TotEstimator(),
            new TaskingEvaluator(),
            new MissionPublisher(),
            new MissionResultSerializer(),
            options ?? new MissionOptions());

    /// <summary>
    /// Process a MissionRequest JSON string and return a MissionResult JSON string. Synchronous,
    /// legacy-equivalent entry point (the publish path is output-neutral and disabled by default).
    /// </summary>
    public string ProcessMission(string inputJson) =>
        ProcessMissionAsync(inputJson).GetAwaiter().GetResult();

    /// <summary>Async pipeline (the distribution step is async). Behaviorally equivalent to legacy.</summary>
    public async Task<string> ProcessMissionAsync(string inputJson, CancellationToken cancellationToken = default)
    {
        ParseOutcome parsed = _parser.Parse(inputJson);
        if (parsed is ParseOutcome.Error err)
        {
            return _serializer.Serialize(BuildParseErrorResult(err.MissionId, err.LaunchEpochSec));
        }

        var request = ((ParseOutcome.Ok)parsed).Request;
        MissionResult result = await ComputeAsync(request, cancellationToken).ConfigureAwait(false);
        return _serializer.Serialize(result);
    }

    private async Task<MissionResult> ComputeAsync(MissionRequest request, CancellationToken ct)
    {
        RouteValidation validation = _routeValidator.Validate(request.Waypoints, _options);
        DistanceResult distance = _distanceCalculator.Compute(request.Waypoints, _options);
        TotResult tot = _totEstimator.Estimate(
            distance.TotalDistanceNm, request.LaunchEpochSec, request.DesiredTotEpochSec, _options);
        bool taskingGo = _taskingEvaluator.Evaluate(validation.RouteValid, request.Platform, request.Variant);

        string? publishStatus = await _publisher
            .PublishAsync(request, distance, validation.RouteValid, taskingGo, _options, ct)
            .ConfigureAwait(false);

        IReadOnlyList<string> messages = BuildMessages(validation, taskingGo, publishStatus);

        return new MissionResult
        {
            MissionId = request.MissionId,
            LegDistancesNm = distance.LegDistancesNm,
            TotalDistanceNm = distance.TotalDistanceNm,
            RouteValid = validation.RouteValid,
            EstimatedTotEpochSec = tot.EstimatedTotEpochSec,
            TotFeasible = tot.TotFeasible,
            TaskingGoNoGo = taskingGo,
            Messages = messages,
        };
    }

    /// <summary>Assemble the message list in the exact legacy order.</summary>
    private static IReadOnlyList<string> BuildMessages(
        RouteValidation validation, bool taskingGo, string? publishStatus)
    {
        var messages = new List<string> { "LEGACY" };
        messages.AddRange(validation.Messages);
        if (!validation.RouteValid) messages.Add("ROUTE_INVALID");
        if (!taskingGo) messages.Add("TASKING_NO_GO");
        if (publishStatus is not null) messages.Add(publishStatus);
        return messages;
    }

    /// <summary>
    /// Legacy parse-error result: ["LEGACY", "PARSE_ERROR"], empty legs, zeroed distance/flags, and
    /// estimatedTot = the partially-parsed launchEpochSec (faithful to the legacy local-variable
    /// return). No corpus vector hits this path, but it is preserved for byte-fidelity.
    /// </summary>
    private static MissionResult BuildParseErrorResult(string missionId, long launchEpochSec) => new()
    {
        MissionId = missionId,
        LegDistancesNm = Array.Empty<double>(),
        TotalDistanceNm = 0.0,
        RouteValid = false,
        EstimatedTotEpochSec = launchEpochSec,
        TotFeasible = false,
        TaskingGoNoGo = false,
        Messages = new[] { "LEGACY", "PARSE_ERROR" },
    };
}

// Composition root / lightweight dependency-injection wiring for the modern mission component.
//
// The legacy read global static config deep inside one method. The modern component instead
// composes single-responsibility collaborators here and injects immutable MissionOptions. This
// self-contained factory keeps the offline/air-gapped build dependency-free (no external DI
// package needed), while still expressing explicit constructor injection — every collaborator is
// an interface, swappable for tests or alternative implementations.

using ForgeEvolve.ModernMds.Distribution;
using ForgeEvolve.ModernMds.Geometry;
using ForgeEvolve.ModernMds.Models;
using ForgeEvolve.ModernMds.Parsing;
using ForgeEvolve.ModernMds.Routing;
using ForgeEvolve.ModernMds.Serialization;
using ForgeEvolve.ModernMds.Tasking;
using ForgeEvolve.ModernMds.Timing;

namespace ForgeEvolve.ModernMds.Services;

/// <summary>
/// Builds a fully-wired <see cref="MissionService"/> from injectable collaborators. Callers may
/// supply their own implementations (e.g. a fake publisher in tests) or accept the defaults.
/// </summary>
public sealed class MissionServiceFactory
{
    private readonly MissionOptions _options;
    private readonly IMissionParser _parser;
    private readonly IRouteValidator _routeValidator;
    private readonly IDistanceCalculator _distanceCalculator;
    private readonly ITotEstimator _totEstimator;
    private readonly ITaskingEvaluator _taskingEvaluator;
    private readonly IMissionPublisher _publisher;
    private readonly IMissionResultSerializer _serializer;

    public MissionServiceFactory(
        MissionOptions? options = null,
        IMissionParser? parser = null,
        IRouteValidator? routeValidator = null,
        IDistanceCalculator? distanceCalculator = null,
        ITotEstimator? totEstimator = null,
        ITaskingEvaluator? taskingEvaluator = null,
        IMissionPublisher? publisher = null,
        IMissionResultSerializer? serializer = null)
    {
        // Defaulting is delegated to Or(...) so this constructor stays trivial (CC 1) — each null
        // check lives in its own tiny method instead of inflating one composition method.
        _options = options ?? new MissionOptions();
        _parser = Or<IMissionParser>(parser, static () => new MissionParser());
        _routeValidator = Or<IRouteValidator>(routeValidator, static () => new RouteValidator());
        _distanceCalculator = Or<IDistanceCalculator>(distanceCalculator, static () => new DistanceCalculator());
        _totEstimator = Or<ITotEstimator>(totEstimator, static () => new TotEstimator());
        _taskingEvaluator = Or<ITaskingEvaluator>(taskingEvaluator, static () => new TaskingEvaluator());
        _publisher = Or<IMissionPublisher>(publisher, static () => new MissionPublisher());
        _serializer = Or<IMissionResultSerializer>(serializer, static () => new MissionResultSerializer());
    }

    /// <summary>Return <paramref name="provided"/> if non-null, else build the default. CC 2.</summary>
    private static T Or<T>(T? provided, Func<T> makeDefault) where T : class =>
        provided ?? makeDefault();

    /// <summary>Construct the wired service.</summary>
    public MissionService Build() => new(
        _parser, _routeValidator, _distanceCalculator, _totEstimator,
        _taskingEvaluator, _publisher, _serializer, _options);
}

// Tasking responsibility, extracted from the legacy god method.
//
// BEHAVIOR-PRESERVING and BUG-FREE: the purely categorical GO/NO-GO rule, preserved exactly.
//   GO requires routeValid AND NOT (variant == "MST" AND platform == "SSN").
//   MST is surface-only, so MST-on-SSN is always NO-GO.

namespace ForgeEvolve.ModernMds.Tasking;

/// <summary>Evaluates the categorical tasking GO/NO-GO decision. Single responsibility.</summary>
public interface ITaskingEvaluator
{
    bool Evaluate(bool routeValid, string platform, string variant);
}

/// <inheritdoc />
public sealed class TaskingEvaluator : ITaskingEvaluator
{
    public bool Evaluate(bool routeValid, string platform, string variant)
    {
        if (!routeValid)
        {
            return false;
        }
        if (variant == "MST" && platform == "SSN")
        {
            return false;
        }
        return true;
    }
}

// Time-on-target responsibility, extracted from the legacy god method.
//
// BEHAVIOR-PRESERVING — reproduces D3 EXACTLY:
//   * travel time is cast to long via TRUNCATION toward zero ((long) cast), NOT rounding;
//   * the synthetic leap-second adjustment is OMITTED entirely (the boundaries table is carried in
//     MissionOptions for the ECP-recommended fix but is deliberately NOT applied here).
// estimatedTot = launch + truncate(total / speed); feasible iff |estimatedTot - desiredTot| <= tol.

using ForgeEvolve.ModernMds.Models;

namespace ForgeEvolve.ModernMds.Timing;

/// <summary>Estimates time-on-target and feasibility. Single responsibility.</summary>
public interface ITotEstimator
{
    TotResult Estimate(double totalDistanceNm, long launchEpochSec, long desiredTotEpochSec, MissionOptions options);
}

/// <inheritdoc />
public sealed class TotEstimator : ITotEstimator
{
    public TotResult Estimate(
        double totalDistanceNm,
        long launchEpochSec,
        long desiredTotEpochSec,
        MissionOptions options)
    {
        // D3: truncation toward zero (NOT round), and NO leap-second adjustment.
        long travelSec = (long)(totalDistanceNm / options.NominalSpeedNmPerSec);
        long estimatedTot = launchEpochSec + travelSec;
        bool feasible = Math.Abs(estimatedTot - desiredTotEpochSec) <= options.TotTolSec;
        return new TotResult(estimatedTot, feasible);
    }
}
